
import {SQL} from 'bun';
import {createHash,randomBytes} from 'node:crypto';
const db=Bun.env.DATABASE_URL?new SQL(Bun.env.DATABASE_URL,{max:4}):null;
const sha=x=>createHash('sha256').update(x).digest('hex');
const niches={
'home-services':['Home services','trades businesses','missed buyer enquiries'],
'restaurants':['Hospitality','independent restaurants','guest retention and booking intake'],
'real-estate':['Real estate','boutique real-estate teams','listing response and buyer qualification'],
'ecommerce':['Ecommerce','growing online stores','creative fatigue and conversion bottlenecks'],
'wellness':['Fitness & wellness','fitness studios','class bookings and membership retention'],
'professional':['B2B professionals','service firms','lead qualification and repetitive intake'],
'creators':['Creators','independent experts','content-to-service conversion']
};
const problems={
followup:['slow response to potential clients','qualified enquiries receiving timely responses'],
content:['inconsistent marketing execution','qualified inbound from original content'],
bookings:['lost appointment requests','completed booking enquiries'],
retention:['weak repeat customer engagement','consenting repeat purchase or booking enquiries'],
attribution:['unclear marketing effectiveness','qualified enquiries attributed to a known channel']
};
const services={setup:['a scoped workflow implementation',800,2500],managed:['ongoing content and AI workflow operations',1200,3500],training:['a done-with-you implementation sprint',350,1000]};
const channels={
organic:'Publish practical, original workflow demos and case evidence three times per week. Use one clear referral link and record real clicks.',
partners:'Build five complementary business relationships, propose mutual educational workshops, and track buyer-qualified referrals. Disclose referral compensation.',
outreach:'Research ten genuinely relevant prospects, use lawful and individually relevant messages with sender identification and opt-out when required, then track actual replies.',
ads:'Draft educational creatives and conversion paths. Do not spend until account permissions, content approval and a written spend limit are established.'
};
const j=(v,status=200,extra={})=>new Response(JSON.stringify(v),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store',...extra}});
const bad=(e,code=400)=>j({error:e},code);
const norm=(v,n=120)=>String(v||'').trim().slice(0,n);
const validEmail=s=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s)&&s.length<180;
let initialized=null;
async function init(){if(!db)throw Error('Database unavailable');if(!initialized)initialized=(async()=>{await db.unsafe("CREATE TABLE IF NOT EXISTS shift_users(id BIGSERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,marketing BOOLEAN NOT NULL DEFAULT FALSE,utm JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");await db.unsafe("CREATE TABLE IF NOT EXISTS shift_sessions(token_hash CHAR(64) PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES shift_users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");await db.unsafe("CREATE TABLE IF NOT EXISTS shift_kits(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES shift_users(id) ON DELETE CASCADE,title TEXT NOT NULL,kit JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");await db.unsafe("CREATE TABLE IF NOT EXISTS shift_enquiries(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,description TEXT NOT NULL,budget TEXT NOT NULL,consent BOOLEAN NOT NULL,utm JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");await db.unsafe("CREATE TABLE IF NOT EXISTS shift_events(id BIGSERIAL PRIMARY KEY,event TEXT NOT NULL,value TEXT NOT NULL DEFAULT '',utm JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");})().catch(e=>{initialized=null;throw e});return initialized}
function makeBlueprint(d){
const industry=niches[d.niche],problem=problems[d.problem],service=services[d.model],route=channels[d.channel],target=Number(d.target),buyer=norm(d.buyer,110).replace(/[\r\n]/g,' '),experience=d.experience;
if(!industry||!problem||!service||!route||!['starter','some','expert'].includes(experience)||![1000,3000,10000,25000].includes(target)||buyer.length<8)throw Error('Complete all seven questions with a specific buyer.');
const factor=experience==='expert'?1.4:experience==='some'?1.15:1,low=Math.round(service[1]*factor/50)*50,high=Math.round(service[2]*factor/50)*50,mid=Math.round((low+high)/2),required=Math.ceil(target/mid);
const positioning='We help '+buyer+' improve '+problem[0]+' using '+service[0]+'; success is measured through '+problem[1]+'.';
const offer='14-day discovery and validation pilot for '+buyer+'. Deliver one approved operating workflow, documented exceptions, a measurable baseline, and a human handover. Scope and final price depend on buyer discovery.';
const deliver=['Document current process and actual baseline for '+problem[1],'Agree permitted tool access, customer consent, and human approvals','Implement and test a bounded workflow around '+problem[0],'Conduct client acceptance checks and exception testing','Provide training, measurement report and clear support boundaries'];
const outreach='SUBJECT: Workflow improvement idea for '+buyer+'\n\nHi [first name],\n\nI work on '+problem[0]+' for '+buyer+'. I can share a brief process map showing where manual handoffs fail and how '+problem[1]+' could be measured with human review. Would that be useful?\n\n[Your name, business identity and legally required opt-out]';
const discovery=['What is currently lost or delayed in this workflow?','What are the real baseline volume, timing and costs?','Which buyer role owns this problem and approves implementation?','What software and data may we legally access?','What acceptance test would make a pilot worthwhile?','Who will own exceptions and support after delivery?'];
const rollout=['DAYS 1–30 / DEMAND: Interview at least ten relevant businesses, quantify the problem from real evidence, and test willingness to pay for one specific pilot.','DAYS 31–60 / DELIVERY: Execute one bounded paid pilot, test exceptions, record true cost and observed results, and collect specific feedback.','DAYS 61–90 / REPEATABILITY: Turn the verified delivery into onboarding checklists, a support model, and consented case studies. Double down on channels with qualified buyer conversations.'];
const blueprint=[
'SHIFT / AGENCY OPERATING BLUEPRINT','User-designed strategy • not real-time market research or guaranteed earnings','',
'01 / BUYER AND OFFER','Ideal client: '+buyer,'Industry: '+industry[0],'Priority bottleneck: '+problem[0],'Positioning: '+positioning,'',
'02 / CLIENT-READY PILOT','Service format: '+service[0],offer,'',
'03 / PACKAGE & REVENUE SCENARIO','Illustrative service pricing: USD $'+low.toLocaleString('en-US')+'–$'+high.toLocaleString('en-US')+' (not market-verified).','Example midpoint: $'+mid.toLocaleString('en-US')+' USD; your hypothetical gross monthly target: $'+target.toLocaleString('en-US')+'.','Number of engagements needed at midpoint: '+required+'. This is division, not a forecast, and excludes all costs, taxes, churn, refunds and sales time.','',
'04 / CLIENT DISCOVERY',...discovery.map((s,i)=>(i+1)+'. '+s),'',
'05 / IMPLEMENTATION ACCEPTANCE',...deliver.map((s,i)=>(i+1)+'. '+s),'',
'06 / FIRST CUSTOMER ACQUISITION',route,'',
'07 / RESPONSIBLE OUTREACH',outreach,'',
'08 / THE NEXT 90 DAYS',...rollout,'',
'09 / ONE-PAGE CLIENT PROPOSAL','Problem: '+problem[0],'Outcome to measure: '+problem[1],'Scope: '+service[0],'Acceptance criteria: documented baseline, approved workflow, tested exceptions, owner handover.','Commercial: final scope, pricing and support terms agreed in writing before work begins.','',
'10 / CONSTRAINTS','Do not claim guaranteed income, fabricate customer evidence or send unsolicited noncompliant marketing. Require explicit approval for any campaign budget, customer-data access and live automation. Pricing is illustrative only.'
].join('\n');
return {title:industry[0]+' · AI Agency Blueprint',intro:'A strategic operating blueprint for '+buyer+'.',blueprint,math:{target,midpoint:mid,required},hooks:['What if '+industry[1]+' could reduce '+problem[0]+'?','The most expensive handoff in '+industry[0].toLowerCase()+' is often the one nobody measures.'],ads:['Explore a clearly scoped process improvement for '+industry[1]+'. Get a workflow map, not a revenue guarantee.'],plan:rollout,outreach,positioning,offer,deliverables:deliver,platform:'LinkedIn'};
}
const limits=new Map();
function limited(req,k,max){if(limits.size>25000)limits.clear();const ip=(req.headers.get('cf-connecting-ip')||req.headers.get('x-forwarded-for')||'unknown').split(',')[0].slice(0,72),key=k+':'+ip,old=limits.get(key),now=Date.now();if(!old||old.exp<now){limits.set(key,{exp:now+3600000,n:1});return false}old.n++;return old.n>max}
function cookies(req){return (req.headers.get('cookie')||'').split(';').map(x=>x.trim()).find(x=>x.startsWith('shift_session='))?.slice(14)||''}
async function active(req){const token=cookies(req);if(!token)return null;await init();const r=await db.unsafe("SELECT u.id,u.email,u.marketing FROM shift_sessions s JOIN shift_users u ON s.user_id=u.id WHERE s.token_hash=$1 AND s.expires_at>NOW() LIMIT 1",[sha(token)]);return r[0]||null}
async function session(id){const token=randomBytes(32).toString('hex');await db.unsafe("INSERT INTO shift_sessions(token_hash,user_id,expires_at) VALUES ($1,$2,NOW()+INTERVAL '30 days')",[sha(token),id]);return 'shift_session='+token+'; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=2592000'}
async function read(req){const s=await req.text();if(s.length>19000)throw Error('Payload too large');return JSON.parse(s||'{}')}
function origin(req){const o=req.headers.get('origin');if(!o)return true;try{return new URL(o).host===new URL(req.url).host}catch{return false}}

